WITH account_summary AS (SELECT account_id, MAX(amount) - MIN(amount) AS amount_range, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list FROM transactions GROUP BY account_id) SELECT accounts.customer_id, accounts.opened_date, account_summary.amount_range, account_summary.merchant_list FROM accounts INNER JOIN account_summary ON accounts.id = account_summary.account_id WHERE account_summary.amount_range >= 72
